/*
 * The only way a Creation is added or changed, apart from handIn's "Also add it to My creations".
 * Whose it is comes from the session. Kinds are SCOPE R7's six (backend/schema.json creationKind).
 * A file is judged as handIn judges a hand-in (its bytes, sniffed into _Files), from the same list:
 * change TYPES here, in handIn and in Option sets/Hand-in kinds together.
 * Editing never changes what a creation holds when it points at a hand-in, nor swaps its file.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const KINDS = ['document', 'interactive', 'prompt', 'audio_video', 'link', 'other'];
    const MAX_BYTES = 50 * 1024 * 1024;
    const MEDIA = ['application/octet-stream'];
    const OFFICE = ['application/zip'];
    const TYPES = {
      pdf: ['application/pdf'], docx: OFFICE, pptx: OFFICE, xlsx: OFFICE,
      html: ['text/html'], htm: ['text/html'],
      png: ['image/png'], jpg: ['image/jpeg'], jpeg: ['image/jpeg'], webp: ['image/webp'],
      mp3: ['audio/mpeg'], m4a: MEDIA.concat(['audio/mp4']), mp4: MEDIA.concat(['video/mp4']), webm: MEDIA.concat(['video/webm', 'audio/webm'])
    };
    const checkLink = (raw) => {
      const url = String(raw || '').trim();
      let ok = false;
      try { const u = new URL(url); ok = (u.protocol === 'https:' || u.protocol === 'http:') && !!u.hostname; } catch (e) { ok = false; }
      if (!ok) return { why: 'That is not a web address. Links start with https://' };
      if (url.length > 2000) return { why: 'That link is too long. Use a shorter share link.' };
      return { url };
    };
    const checkText = (raw) => {
      const text = String(raw || '');
      if (!text.trim()) return { why: 'Write or paste something to keep.' };
      if (text.length > 50000) return { why: 'That is too long to paste. Keep it under 50,000 characters, or add it as a file.' };
      return { text };
    };

    const title = String(Inputs.title || '').trim();
    if (!title) return refuse('Give it a title.');
    if (title.length > 200) return refuse('Keep the title under 200 characters.');
    const kind = String(Inputs.kind || '');
    if (!KINDS.includes(kind)) return refuse('Choose what kind of thing it is.');
    const madeWith = String(Inputs.madeWith || '').trim();
    if (madeWith.length > 200) return refuse('Keep "Made with" under 200 characters.');
    const description = String(Inputs.description || '').trim();
    if (description.length > 2000) return refuse('Keep the description under 2,000 characters.');
    const words = { title, kind, madeWith: madeWith || null, description: description || null, usedInClass: Inputs.usedInClass === true };

    const id = String(Inputs.id || '');
    let savedId = id;
    if (id) {
      const rows = await q('Creation', { objectId: { equalTo: id } });
      const row = rows[0];
      if (!row || row.learner !== me) return refuse('This is not one of your creations. Reload the page.');
      const change = Object.assign({}, words);
      if (!row.submission && !row.file) {
        if (row.url) {
          const l = checkLink(Inputs.url);
          if (l.why) return refuse(l.why);
          change.url = l.url;
        } else if (row.text) {
          const t = checkText(Inputs.text);
          if (t.why) return refuse(t.why);
          change.text = t.text;
        }
      }
      await Noodl.Records.save(id, change, { className: 'Creation' });
    } else {
      const row = Object.assign({ learner: me, fromStep: null, submission: null }, words);
      const form = String(Inputs.form || '');
      if (form === 'file') {
        const name = String(Inputs.file || '');
        if (!name) return refuse('Choose a file to keep.');
        const found = await q('_Files', { storedName: { equalTo: name } });
        const f = found.length === 1 ? found[0] : null;
        const owner = f && f.owner && typeof f.owner === 'object' ? f.owner.objectId : f && f.owner;
        if (!f || owner !== me) return refuse('That file is not one you uploaded. Choose it and upload it again.');
        if (f.private !== true) return refuse('That file was not uploaded privately. Choose it and upload it again.');
        if (Number(f.size) > MAX_BYTES) return refuse('That file is larger than 50 MB. Put it online and add a link instead.');
        const original = String(f.originalName || '');
        const dot = original.lastIndexOf('.');
        const ext = dot > 0 ? original.slice(dot + 1).toLowerCase() : '';
        const allowed = TYPES[ext];
        if (!allowed) return refuse('Files of this kind can\'t be kept here. Use Word, PowerPoint, Excel, PDF, HTML, an image (PNG, JPG, WebP), audio (MP3, M4A) or video (MP4, WebM), or add a link.');
        if (!allowed.includes(f.contentType)) return refuse('This file is not a real .' + ext + ' file. Save it again in that format, then add it.');
        row.file = name;
        row.fileName = original;
      } else if (form === 'link') {
        const l = checkLink(Inputs.url);
        if (l.why) return refuse(l.why);
        row.url = l.url;
      } else if (form === 'text') {
        const t = checkText(Inputs.text);
        if (t.why) return refuse(t.why);
        row.text = t.text;
      } else {
        return refuse('Choose a file, a link or some text to keep.');
      }
      const created = await Noodl.Records.create('Creation', row, { plain: true });
      savedId = created.objectId || created.id;
    }
    await Noodl.Records.create('Doorbell', { learner: me, topic: 'creation' },
      { acl: { [me]: { read: true }, 'role:staff': { read: true } } });
    Outputs.creationId = savedId;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:saveCreation]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
